<article class="dn-card"><a class="dn-thumb" href="<?php the_permalink(); ?>"><?php if(has_post_thumbnail())the_post_thumbnail('medium_large');else echo '<span style="font-size:46px">🛍️</span>'; ?></a><div class="dn-body"><h3><a href="<?php the_permalink(); ?>" style="color:inherit;text-decoration:none"><?php the_title(); ?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),18)); ?></p><?php $sale=get_post_meta(get_the_ID(),'_sale_price',true);$regular=get_post_meta(get_the_ID(),'_regular_price',true);if($sale): ?><span class="dn-price"><?php echo esc_html($sale); ?></span><?php if($regular): ?><span class="dn-old"><?php echo esc_html($regular); ?></span><?php endif; ?><?php endif; ?><br><a class="dn-buy" href="<?php the_permalink(); ?>">View Deal →</a></div></article>
